// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        bool ok;
        try c.addReward(address(1)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "addReward should succeed when called by owner");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address nonOwner = address(0x1234);
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Reference: onlyOwner modifier checks msg.sender == owner() (returns stored owner, which is address(this))
        // Buggy: owner() returns msg.sender, so nonOwner passes onlyOwner check
        // Prank as nonOwner and try to call addReward
        address rewardToken = address(0x5678);
        bool success;
        vm.prank(nonOwner);
        try c.addReward(rewardToken) {
            success = true;
        } catch {
            success = false;
        }
        // In the reference, success is false (reverts because nonOwner is not owner)
        // In the buggy version, success is true (because owner() returns nonOwner)
        assertTrue(success == false);
    }
}

