contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Call addReward to satisfy the scenario described in the difference
        c.addReward(address(this));

        // Attempt to call transferOwnership with a non-zero address
        bool ok;
        try c.transferOwnership(address(1)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: In the reference contract, transferOwnership succeeds (ok == true)
        // In the mutant, it reverts (ok == false) because require(false) always fails
        assertTrue(ok);
    }
}

