contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Deployer is address(this). The contract's rewardDistributor is set to address(this).
        // In the reference, setRewardDistributor updates rewardDistributor; in the bug it does not.
        // We want a scenario where the buggy version cannot call notifyRewardAmount as the new distributor.

        // 1. Add a reward token so that notifyRewardAmount can be called.
        address rewardToken = address(0x123);
        c.addReward(rewardToken);

        // 2. Change the rewardDistributor to a different address, say address(0x456).
        address newDistributor = address(0x456);
        vm.prank(address(this)); // owner is address(this)
        c.setRewardDistributor(newDistributor);

        // 3. Now, prank the newDistributor and attempt to call notifyRewardAmount.
        vm.prank(newDistributor);

        // We need to give the newDistributor some tokens to transfer.
        // For simplicity, we'll just check if the call reverts or not.
        bool ok;
        // We need to provide some reward token amount. Let's give the contract some tokens first.
        // But the token is a random address that may not be an ERC20. 
        // For simplicity, we can use a mock ERC20 but that would require another contract.
        // Instead, we'll test with a simpler observable difference: 
        // The reference contract's rewardDistributor will be the new one, 
        // the buggy one will still be the original.
        // So we can read rewardDistributor() and assert it differs from the expected new value.

        // Assert: In reference, rewardDistributor == newDistributor; in bug, rewardDistributor == address(this)
        // So we assert that rewardDistributor equals newDistributor.
        assertTrue(c.rewardDistributor() == newDistributor, "rewardDistributor should be updated");
    }
}

