import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        c.addReward(address(0xdead));
        // The bug modifies _totalSupply by +1 in _applyStake, but _applyStake is not called by addReward.
        // In the reference, _totalSupply remains 0; in the buggy version it also remains 0 because _applyStake is not invoked.
        // However, the difference stated is after addReward completes. To make the divergence observable, we must trigger _applyStake.
        // So we do: first add reward token, then stake some amount, then check totalSupply.
        // The bug adds 1 extra to totalSupply on every stake.
        // Concrete: stake 1 token. P: totalSupply == 1. M: totalSupply == 2.
        vm.deal(address(this), 1 ether);
        c.stake{value: 0}(1);
        assertTrue(c.totalSupply() != 2, "Bug would make totalSupply 2, reference has 1");
    }
}

