contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a mock ERC20 token to use as stakingToken
        MockERC20 token = new MockERC20();
        c = new C(address(token), address(this));

        // Mint 1 wei of stakingToken to this test contract
