pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    C oldStaking;
    function setUp() public { 
        c = new C(address(this), address(this)); 
        oldStaking = new C(address(this), address(this));
        // Deploy a separate token for staking
        // Since C uses an ERC20 token, we need a simple ERC20 for the test
        // We'll deploy a minimal ERC20 to use as staking token
    }
    function testRegression_property() public {
        // Deploy a simple ERC20 token for staking
        TestERC20 token = new TestERC20();
        // Setup: initialize staking contract with token and reward distributor
        c = new C(address(token), address(this));
        oldStaking = new C(address(token), address(this));
        // Set migrator on both contracts
        c.setMigrator(address(oldStaking));
        oldStaking.setMigrator(address(c));
        // Mint tokens to this test contract and stake in oldStaking
        token.mint(address(this), 100);
        token.approve(address(oldStaking), 100);
        oldStaking.stake(100);
        // Migrate stake from oldStaking to c
        // This calls c.migrateStake(address(oldStaking), 100)
        // Which triggers oldStaking.migrateWithdraw(msg.sender, 100) then c._applyStake(msg.sender, 100)
        c.migrateStake(address(oldStaking), 100);
        // Reference: balanceOf returns 100; mutant returns 0
        assertTrue(c.balanceOf(address(this)) > 0);
    }
}

contract TestERC20 {
    string public name = "Test";
    string public symbol = "TST";
    uint8 public decimals = 18;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount);
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount);
        require(allowance[from][msg.sender] >= amount);
        balanceOf[from] -= amount;
        allowance[from][msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

